wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once; this is the only time source the node holds.
        let now = wall_clock::now();

        // The one permitted fetch. A transport failure is a value, so it is
        // reported as zero characters rather than failing the heartbeat.
        // A request outside the allowlist traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat at {} fetched {} chars",
            now.seconds, fetched
        );
        let notified = notifier::notify(&message);

        // The contract requires `notified == true` on every output. If the
        // notifier refuses, do not return a report that claims otherwise:
        // trap instead, so no output violating the ensures is ever produced.
        if !notified {
            panic!("notifier refused the heartbeat; no report produced");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
